gdr.ValidationScript:
var CatalogManagement = Lib.Purchasing.CatalogManagement;
let currentName = Data.GetActionName();
let currentAction = Data.GetActionType();
Log.Info("-- Catalog Management Validation Script -- Name: '" + (currentName ? currentName : "<empty>") + "', Action: '" + (currentAction ? currentAction : "<empty>") + "' , Device: '" + Data.GetActionDevice());
const g_companyCode = Data.GetValue("CompanyCode__") || Variable.GetValueAsString("VendorCompanyCode");
function SendToApproval() {
    let submissionDate = new Date();
    Data.SetValue("SubmissionDateTime__", submissionDate);
    Data.SetValue("Status__", "ToApprove");
    // @TODO Create an instance of the process as Admin
    let catalogManagementWorkflow = Process.CreateProcessInstanceAsProcessAdmin("Catalog management workflow", false, false, false);
    // The Imported CSV file is the first document attached to the CM process
    const csvFile = Attach.GetAttach(0);
    catalogManagementWorkflow.AddAttachEx(csvFile);
    CatalogManagement.Server.SetExtractedDataToTransport(catalogManagementWorkflow);
    let extCMWVars = catalogManagementWorkflow.GetExternalVars();
    extCMWVars.AddValue_String("CMRUIDEX", Data.GetValue("RUIDEX"), true);
    extCMWVars.AddValue_String("SubmissionTime", submissionDate.getTime(), true);
    extCMWVars.AddValue_String("CatalogManagmentType", "external", true);
    extCMWVars.AddValue_String("CatalogManagmentSource", Variable.GetValueAsString("CatalogManagmentSource"), true);
    let CMWVars = catalogManagementWorkflow.GetUninheritedVars();
    CMWVars.AddValue_String("Status__", Data.GetValue("Status__"), true);
    CMWVars.AddValue_String("CompanyCode__", g_companyCode, true);
    CMWVars.AddValue_String("WarehouseNumber__", Data.GetValue("WarehouseNumber__"), true);
    CMWVars.AddValue_String("WarehouseName__", Data.GetValue("WarehouseName__"), true);
    CMWVars.AddValue_String("VendorNumber__", Data.GetValue("VendorNumber__"), true);
    CMWVars.AddValue_String("VendorName__", Data.GetValue("VendorName__"), true);
    CMWVars.AddValue_String("RequesterLogin__", Data.GetValue("RequesterLogin__"), true);
    CMWVars.AddValue_String("RequesterName__", Data.GetValue("RequesterName__"), true);
    if (CatalogManagement.IsFromInboundChannelVendorUpdateRequest()) {
        CMWVars.AddValue_String("ImportDescription__", Language.Translate("_ProcessCreatedByInboundChannel"), true);
    }
    else {
        CMWVars.AddValue_String("ImportDescription__", Data.GetValue("ImportDescription__"), true);
    }
    catalogManagementWorkflow.Process();
    let ret = catalogManagementWorkflow.GetLastError();
    if (ret === 0) {
        Log.Info("CMW process call OK");
        // Set next alert with no parameters in particular
        Lib.CommonDialog.NextAlert.Define("_Update request will be submitted", "_Your catalog update request will be sent for approval", {
            isError: false,
            behaviorName: "CMCreationInfo"
        });
        Data.SetValue("KeepOpenAfterApproval", "WaitForApproval");
    }
    else {
        Log.Error("CMW process call returns with error message : " + catalogManagementWorkflow.GetLastErrorMessage());
    }
    Process.WaitForUpdate();
}
function CSVApproved() {
    Data.SetValue("ValidationDateTime__", new Date());
    Data.SetValue("Status__", "Approved");
    //Notif Succes
}
function CSVRejected() {
    const data = JSON.parse(Variable.GetValueAsString("resumeWithActionData") || "{}");
    Data.SetValue("Reason__", data.rejectionReason);
    Data.SetValue("ValidationDateTime__", new Date());
    Data.SetValue("Status__", "Rejected");
    Data.SetValue("State", 400);
}
function CSVFailed() {
    let now = new Date();
    Data.SetValue("SubmissionDateTime__", now);
    Data.SetValue("ValidationDateTime__", now);
    CatalogManagement.Server.SendEmailNotification(Data.GetValue("OwnerID"), "CM-CatalogManager_ImportFail_Internal.htm", true);
    Data.SetValue("Status__", "Failed");
}
function HandleApprovalWorkflowErrors() {
    const data = JSON.parse(Variable.GetValueAsString("resumeWithActionData") || "{}");
    Log.Error("[Catalog management workflow Error] " + data.errorMsg);
    Variable.SetValueAsString("MissingWorkflowRuleError", "true");
    Data.SetValue("Status__", "Failed");
    Data.SetValue("State", 200);
}
async function InitArchiveDurationForCompanyCode(companyCode) {
    const CCValues = await Lib.P2P.CompanyCodesValue.QueryValues(companyCode, { asAdmin: true });
    Sys.Parameters.GetInstance("PAC").Reload(CCValues.DefaultConfiguration__);
    await Lib.P2P.InitValidityDateTime("PAC");
    await Lib.P2P.InitArchiveDuration("PAC", "ProcurementArchiveDurationPortalInMonths");
}
async function Main() {
    if (!currentName && !currentAction && CatalogManagement.IsFromInboundChannelVendorUpdateRequest()) {
        if (Variable.GetValueAsString("isFirstValidationDone") === "true") {
            if (CatalogManagement.IsInError()) {
                currentName = "CSVFailed";
            }
            else {
                currentName = "Submit";
                await CatalogManagement.ServerVendor.FillInfoForInboundChannelVendorUpdateRequest();
            }
            currentAction = "approve_asynchronous";
            Log.Info("-- Catalog Management Validation Script -- actionName and actionType changed to '" + currentName + "' and '" + currentAction + "' for Inbound Channel Vendor Update Request");
        }
    }
    if (currentAction === "approve_asynchronous" || currentAction === "approve" || currentAction === "ResumeWithAction") {
        switch (currentName) {
            case "Submit":
                SendToApproval();
                break;
            case "CSVApproved":
                CSVApproved();
                break;
            case "CSVRejected":
                CSVRejected();
                break;
            case "CSVFailed":
                CSVFailed();
                break;
            case "MissingWorkflowRules":
                HandleApprovalWorkflowErrors();
                break;
            default:
                Process.PreventApproval();
                break;
        }
    }
    await InitArchiveDurationForCompanyCode(g_companyCode);
    Variable.SetValueAsString("isFirstValidationDone", "true");
}
Lib.P2P.HandleScriptError(Main());
//# sourceMappingURL=validationscript.js.map

gdr.ExtractionScript:
var ExtractionScript;
(function (ExtractionScript) {
    var CatalogManagement = Lib.Purchasing.CatalogManagement;
    class Main {
        constructor(catalogManagementServer) {
            this.catalogManagementServer = catalogManagementServer;
        }
        async Start() {
            if (!Data.GetActionName() && !Data.GetActionType() && !!Data.GetValue("SourceRUID")) {
                Data.SetValue("NeedValidation", 0);
                Variable.SetValueAsString("CatalogManagmentSource", "inboundChannel");
                await CatalogManagement.ServerVendor.FillInfoForInboundChannelVendorUpdateRequest();
            }
            this.catalogManagementServer.Init();
            try {
                await this.catalogManagementServer.ReadCSVAndSetExtractedDataToProcess();
            }
            catch (e) {
                Log.Error(`Error in CSV extraction: ${e.message}`);
                if (e.stack) {
                    Log.Error("StackTrace : " + e.stack);
                }
                Data.SetValue("Status__", "Failed");
                Data.SetValue("State", 100);
            }
            if (this.catalogManagementServer.IsCMSubmitable()) {
                Variable.SetValueAsString("IsCMSubmitable", "true");
            }
            else {
                Variable.SetValueAsString("IsCMSubmitable", "false");
            }
        }
    }
    if (typeof _ENV_TEST_ENABLED === "undefined") {
        let maxlines = parseInt(Variable.GetValueAsString("MAXLINES"));
        if (isNaN(maxlines)) {
            maxlines = CatalogManagement.maxCSVLinesSupported;
        }
        const isInternalUpdateRequest = CatalogManagement.IsInternalVendorUpdateRequest();
        const mappingVendorItem = new CatalogManagement.MappingVendor();
        const catalogManagementServerVendor = new CatalogManagement.ServerVendor(mappingVendorItem, isInternalUpdateRequest, maxlines);
        const main = new Main(catalogManagementServerVendor);
        Lib.P2P.HandleScriptError(main.Start());
    }
})(ExtractionScript || (ExtractionScript = {}));
//# sourceMappingURL=extractionscript.js.map

gdr.PostProcessingScript:
var PostProcessingScript;
(function (PostProcessingScript) {
    if (Data.GetValue("Status__") === "Failed") {
        Data.SetValue("State", 200);
        // Do not archive because document has deleted=1 so it's not visible by the customer.
        Data.SetValue("ArchiveDuration", 0);
    }
})(PostProcessingScript || (PostProcessingScript = {}));
//# sourceMappingURL=postprocessingscript.js.map

ui.CustomScript:
/* eslint-disable class-methods-use-this */
var CustomScript;
(function (CustomScript) {
    var CatalogManagement = Lib.Purchasing.CatalogManagement;
    let CompanyHelper;
    (function (CompanyHelper) {
        CompanyHelper.hasError = false;
        let VendorLinkInfo = {};
        function GetCompanyValues() {
            const comboValues = [];
            const companies = VendorLinkInfo;
            if (Object.keys(companies).length === 0) {
                return comboValues;
            }
            for (const companyCode in companies) {
                if (companies.hasOwnProperty(companyCode)) {
                    comboValues.push(companyCode + "=" + companies[companyCode].CompanyName__);
                }
            }
            return comboValues;
        }
        CompanyHelper.GetCompanyValues = GetCompanyValues;
        function GetVendorNumber() {
            return VendorLinkInfo[Data.GetValue("CompanyCode__")].VendorNumber__;
        }
        CompanyHelper.GetVendorNumber = GetVendorNumber;
        function GetVendorName() {
            return VendorLinkInfo[Data.GetValue("CompanyCode__")].VendorName__;
        }
        CompanyHelper.GetVendorName = GetVendorName;
        function InitCompanyBrowse() {
            if (Variable.GetValueAsString("vendorLinksInfos") !== "{}") {
                VendorLinkInfo = JSON.parse(Variable.GetValueAsString("vendorLinksInfos"));
                const comboValues = GetCompanyValues();
                const selectedCompanyCode = Data.GetValue("CompanyCode__");
                if (comboValues.length) {
                    Controls.CompanyCode__.SetText(comboValues.join("\n"));
                    Controls.CompanyCode__.SetRequired(true);
                }
                if (selectedCompanyCode && selectedCompanyCode !== "null") {
                    if (!comboValues.length) {
                        Controls.CompanyCode__.SetText(selectedCompanyCode);
                    }
                    Controls.CompanyCode__.SetValue(selectedCompanyCode);
                }
                Controls.CompanyCode__.Hide(comboValues.length <= 1);
            }
            else {
                CompanyHelper.hasError = true;
                Controls.CompanyCode__.Hide(true);
                Popup.Alert(["_PleaseContactYourBuyer:No Vendor link record"], true, null, "_Submission failed");
            }
        }
        CompanyHelper.InitCompanyBrowse = InitCompanyBrowse;
    })(CompanyHelper || (CompanyHelper = {}));
    class Main {
        constructor(catalogManagementClientVendor) {
            this.catalogManagementClientVendor = catalogManagementClientVendor;
            this.currentStatus = Data.GetValue("Status__");
        }
        InitImportStep() {
            Controls.HelpDescription__.SetWidth("495px");
            Controls.HelpDescription__.Hide(false);
            Controls.ImportStepButton__.SetTextColor("color8");
            Controls.WorkflowStepButton__.SetTextColor("color9");
            Controls.SummaryStepButton__.SetTextColor("color9");
            Controls.GeneralInformationsPane.Hide(false);
            Controls.Status__.Hide(true);
            Controls.Reason__.Hide(true);
            Controls.RequesterLogin__.Hide(true);
            Controls.RequesterName__.Hide(true);
            if (Sys.Helpers.IsEmpty(Data.GetValue("RequesterLogin__"))) {
                Data.SetValue("RequesterLogin__", User.loginId);
                Data.SetValue("RequesterName__", User.fullName);
                Controls.CompanyCode__.Hide(true);
            }
            else {
                CompanyHelper.InitCompanyBrowse();
            }
            Controls.SubmissionDateTime__.Hide(true);
            Controls.ValidationDateTime__.Hide(true);
            Controls.ImportDescription__.Hide(false);
            Controls.DownloadTemplate__.Hide(false);
            const lineDisplayed = this.catalogManagementClientVendor.DisplayPreviews(true);
            const CSVhasError = this.catalogManagementClientVendor.DisplayParsingError();
            const previousCompanyCode = Data.GetValue("CompanyCode__");
            Controls.CompanyCode__.OnChange = function () {
                function onConfirmOKClick() {
                    Data.SetValue("VendorNumber__", CompanyHelper.GetVendorNumber());
                    Data.SetValue("VendorName__", CompanyHelper.GetVendorName());
                    //DO NOT CHANGE ACTION NAME : Document action name is used with keepUserDataWhenChangingDocument to keep the user Data when reprocessing
                    ProcessInstance.Resubmit("Document");
                }
                function onConfirmCancelClick() {
                    Data.SetValue("CompanyCode__", previousCompanyCode);
                }
                Popup.Confirm(["_The document will be reprocessed: Do you want to continue ?"], false, onConfirmOKClick, onConfirmCancelClick, "_CompanyCode changed");
            };
            Controls.Submit.SetLabel("_Send to approval");
            if (Variable.GetValueAsString("IsCMSubmitable") === "false") {
                Popup.Alert(["_PleaseContactYourBuyer:CM already being validated"], true, null, "_Submission failed");
                Controls.Submit.SetDisabled(true);
            }
            else {
                Controls.Submit.SetDisabled(CompanyHelper.hasError || CSVhasError || Attach.GetNbAttach() === 0 || lineDisplayed === 0);
            }
        }
        InitAttachmentsPane() {
            const hasAttachment = !!Attach.GetNbAttach();
            ProcessInstance.DisableAttachmentUpload(hasAttachment);
            Controls.AttachmentsPane.OnAttachmentAdded = function () {
                if (Data.GetValue("Status__") === "Draft") {
                    if (Attach.GetNbAttach() > 1) {
                        Attach.RemoveAttach(0);
                    }
                    ProcessInstance.Resubmit("Document");
                }
            };
        }
        InitWorkflowStep() {
            Controls.HelpDescription__.Hide();
            Controls.ImportStepButton__.SetTextColor("color9");
            Controls.WorkflowStepButton__.SetTextColor("color8");
            Controls.SummaryStepButton__.SetTextColor("color9");
            Controls.ParsingErrorsPane.Hide(true);
            Controls.GeneralInformationsPane.Hide(false);
            CompanyHelper.InitCompanyBrowse();
            Controls.Status__.Hide(false);
            Controls.Reason__.Hide(true);
            Controls.RequesterLogin__.Hide(true);
            Controls.RequesterName__.Hide(true);
            Controls.SubmissionDateTime__.Hide(false);
            Controls.ValidationDateTime__.Hide(true);
            Controls.ImportDescription__.Hide(false);
            Controls.DownloadTemplate__.Hide(true);
            this.catalogManagementClientVendor.DisplayPreviews(true);
            this.catalogManagementClientVendor.DisplayParsingError();
            Controls.Submit.Hide(true);
            if (Variable.GetValueAsString("MissingWorkflowRuleError") == "true") {
                Popup.Alert(["_Approval workflow not set correctly on buyer side"], true, null, "_Workflow approval error");
            }
        }
        InitResultStep() {
            Controls.HelpDescription__.Hide();
            Controls.ImportStepButton__.SetTextColor("color9");
            Controls.WorkflowStepButton__.SetTextColor("color9");
            Controls.SummaryStepButton__.SetTextColor("color8");
            Controls.GeneralInformationsPane.Hide(false);
            CompanyHelper.InitCompanyBrowse();
            Controls.Status__.Hide(false);
            Controls.Reason__.Hide(Sys.Helpers.IsEmpty(Data.GetValue("Reason__")));
            Controls.RequesterLogin__.Hide(true);
            Controls.RequesterName__.Hide(true);
            Controls.ParsingErrorsPane.Hide(true);
            Controls.SubmissionDateTime__.Hide(false);
            Controls.ValidationDateTime__.Hide(false);
            Controls.ImportDescription__.Hide(false);
            Controls.DownloadTemplate__.Hide(true);
            Controls.CompanyCode__.SetReadOnly(true);
            Controls.ImportDescription__.SetReadOnly(false);
            if (this.currentStatus !== "Rejected") {
                this.catalogManagementClientVendor.DisplayPreviews(true);
            }
            else {
                this.catalogManagementClientVendor.DisplayPreviews(false);
            }
            Controls.Submit.Hide(true);
        }
        HideTechnicalFields() {
            Controls.NextProcess.Hide(true);
            Controls.SystemData.Hide(true);
        }
        Start() {
            Variable.SetValueAsString("CatalogManagmentType", "external");
            Process.SetHelpId("5022");
            ProcessInstance.SetSilentChange(true);
            this.InitAttachmentsPane();
            switch (this.currentStatus) {
                case "ToApprove":
                case "Failed":
                    this.InitWorkflowStep();
                    break;
                case "Approved":
                case "Rejected":
                case "Reverted":
                    this.InitResultStep();
                    break;
                case "Draft":
                default:
                    this.InitImportStep();
                    break;
            }
            this.HideTechnicalFields();
            // Show next alert notifications
            Lib.CommonDialog.NextAlert.Show({
                "CMCreationInfo": {
                    IsShowable: function () {
                        return !!Data.GetActionName();
                    },
                    Popup: function (nextAlert) {
                        Popup.Alert([nextAlert.message], false, () => {
                            ProcessInstance.Quit("quit");
                        }, nextAlert.title, true);
                    }
                }
            });
        }
    }
    CustomScript.Main = Main;
    if (typeof _ENV_TEST_ENABLED === "undefined") {
        const isInternalVendorUpdateRequest = CatalogManagement.IsInternalVendorUpdateRequest();
        const catalogManagementClientVendor = new CatalogManagement.ClientVendor(isInternalVendorUpdateRequest);
        const main = new Main(catalogManagementClientVendor);
        main.Start();
    }
})(CustomScript || (CustomScript = {}));
//# sourceMappingURL=customscript.js.map

